#include <iostream>
#include <memory>
#include <string>
using namespace std;

struct Fish {
    string name;
    Fish(string n) : name(n) { cout << "领到 " << name << endl; }
    ~Fish() { cout << "还回 " << name << endl; }
};

int main() {
    {
        unique_ptr<Fish> p = make_unique<Fish>("大肥鱼");
        cout << p->name << endl;
    }
    cout << "收工" << endl;
    return 0;
}

#include <iostream>
#include <memory>
using namespace std;

int main() {
    shared_ptr<int> a = make_shared<int>(5);
    cout << a.use_count() << endl;
    {
        shared_ptr<int> b = a;
        cout << a.use_count() << endl;
    }
    cout << a.use_count() << endl;
    return 0;
}
